import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, useWindowDimensions, type ViewStyle } from "react-native";
import { Canvas, Picture, Skia, createPicture } from "@shopify/react-native-skia";
import { useDerivedValue, useFrameCallback, useSharedValue } from "react-native-reanimated";
import { WATCH_DEFAULTS, createWatch, stepWatch, trainAngles, windCrown, type WatchState } from "./watchMath";
import { buildWatchScene, renderWatch, type Camera, type Tri } from "./watch3d";

export type MechanicalWatchProps = {
  /** Render size in points (square). */
  size?: number;
  reducedMotion?: boolean;
  /** Beat haptics: fired on each escapement lock arrest. */
  onBeat?: () => void;
  label?: string;
  style?: ViewStyle;
};

const CAM0: Camera = { yaw: 0.35, pitch: 0.55, dist: 150, fov: 0.73, cx: 0, cy: 0 };

export function MechanicalWatch({ size = 340, reducedMotion, onBeat, label = "Mechanical watch", style }: MechanicalWatchProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled().then((v) => alive && setSystemReduce(v)).catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => { alive = false; sub.remove(); };
  }, []);
  const reduce = reducedMotion ?? systemReduce;

  const scene = useMemo(() => buildWatchScene(), []);
  const sim = useSharedValue<WatchState>(createWatch(WATCH_DEFAULTS));
  const frame = useSharedValue(0);
  const camSV = useSharedValue<Camera>({ ...CAM0 });
  const dragging = useSharedValue(false);
  const reduceM = useSharedValue(false);
  const windCmd = useSharedValue(0);       // crown wind requests (turns)
  const lastBeat = useSharedValue(0);
  const latest = useRef({ reduce, onBeat });
  latest.current = { reduce, onBeat };
  useEffect(() => { reduceM.value = reduce; }, [reduce, reduceM]);

  /* drag orbits the camera; vertical two-finger... keep it one finger:
     horizontal drag = yaw, vertical = pitch; quick flick on the crown edge
     winds (later: dedicated crown hit zone). */
  const gesture = useRef({ yaw: CAM0.yaw, pitch: CAM0.pitch });
  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onPanResponderGrant: () => {
          gesture.current.yaw = camSV.value.yaw;
          gesture.current.pitch = camSV.value.pitch;
          dragging.value = true;
        },
        onPanResponderMove: (_e, gs) => {
          camSV.value = {
            ...camSV.value,
            yaw: gesture.current.yaw + gs.dx / 140,
            pitch: Math.max(-1.1, Math.min(1.3, gesture.current.pitch + gs.dy / 180)),
          };
        },
        onPanResponderRelease: () => { dragging.value = false; },
        onPanResponderTerminate: () => { dragging.value = false; },
      }),
    [camSV, dragging],
  );

  useFrameCallback((info) => {
    if (reduceM.value) return;
    const s = sim.value;
    while (windCmd.value > 0) { windCrown(s, WATCH_DEFAULTS, 0.5); windCmd.value -= 1; }
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    stepWatch(s, WATCH_DEFAULTS, dt);
    if (!dragging.value) {
      const c = camSV.value;
      camSV.value = { ...c, yaw: c.yaw + dt * 0.12 };   // idle turntable
    }
    frame.value = frame.value + 1;
  });

  const picture = useDerivedValue(() => {
    frame.value;
    const rect = { x: 0, y: 0, width: size, height: size };
    const s = sim.value;
    const a = trainAngles(s.e);
    const tris: Tri[] = [];
    renderWatch(scene, {
      barrel: a.barrel, center: a.center, third: a.third, fourth: a.fourth, escape: a.escape,
      fork: s.p, balance: s.b, hour: -a.hour, minute: -a.minute, second: -a.second,
    }, camSV.value, size, tris);
    return createPicture((canvas) => {
      const bg = Skia.Paint();
      bg.setAntiAlias(true);
      bg.setColor(Float32Array.of(0.035, 0.035, 0.045, 1));
      canvas.drawRect(rect, bg);
      const paint = Skia.Paint();
      paint.setAntiAlias(true);
      const path = Skia.Path.Make();
      let cr = -1, cg = -1, cb = -1;
      for (let i = 0; i < tris.length; i++) {
        const t = tris[i];
        // 12-bit color bucket: flush the run when the quantized color changes
        const qr = (t.r * 15) | 0, qg = (t.g * 15) | 0, qb = (t.b * 15) | 0;
        if (qr !== cr || qg !== cg || qb !== cb) {
          if (cr >= 0) { canvas.drawPath(path, paint); path.rewind(); }
          cr = qr; cg = qg; cb = qb;
          paint.setColor(Float32Array.of((qr + 0.5) / 15, (qg + 0.5) / 15, (qb + 0.5) / 15, 1));
        }
        path.moveTo(t.x0, t.y0);
        path.lineTo(t.x1, t.y1);
        path.lineTo(t.x2, t.y2);
        path.close();
      }
      if (cr >= 0) canvas.drawPath(path, paint);
    }, rect);
  }, [size]);

  return (
    <View style={[{ width: size, height: size }, style]} {...pan.panHandlers} accessibilityLabel={label}>
      <Canvas pointerEvents="none" style={{ width: size, height: size }}>
        <Picture picture={picture} />
      </Canvas>
    </View>
  );
}

export default MechanicalWatch;

/* Mechanical watch shared simulation. Pure TypeScript, no closures over
   component state, so Reanimated can run every function on the UI thread.
   Model: a hand-wound Swiss-lever movement.
   - Gear train ratios are exact by construction: they come from tooth
     counts (barrel 72 -> center pinion 12, center 80 -> third pinion 10,
     third 75 -> fourth pinion 10, fourth 70 -> escape pinion 7), so the
     escape wheel turns once per 6 s at 6 beats/s (21,600 vph, 3 Hz
     balance), the fourth wheel carries the seconds hand at 1 rev/min, the
     center wheel the minute hand at 1 rev/hour, hour hand via 12:1 motion
     works. No hand or wheel has its own animator; every angle derives from
     the escape wheel through the tooth counts.
   - Escapement is an active-set impulse contact model on three rigid
     bodies: escape wheel (club-tooth tips as contact points), pallet fork
     (entry/exit stones with locking + impulse faces), balance wheel
     (hairspring oscillator with roller jewel engaging the fork horns).
     Locking, draw, unlocking, impulse, drop and recoil all emerge from
     contact geometry and mainspring torque - no code schedules a beat.
   - Simplifications, named: tooth/pallet contact is tooth-tip point vs
     pallet face segments (the real sliding pair is club plane vs stone
     plane); the guard-pin safety action is omitted; restarting from a
     full stop is seeded with a small impulse standing in for the handling
     jolt (real self-start geometry is not modeled); power reserve is
     accelerated so winding stays part of the interaction.
   This is a contact solver over point-face pairs, not a scripted
   state machine - the same idealisation class as the desk toys, applied
   to horology. */

export type WatchPhysics = {
  escapeTeeth: number;      // 15 club teeth
  escapeR: number;          // tip circle radius
  forkPivot: number;        // distance escape center -> pallet arbor (pivot ABOVE wheel)
  balancePivot: number;     // distance pallet arbor -> balance staff
  rollerR: number;          // roller jewel radius from balance staff
  hornR: number;            // pallet arbor -> horn slot center
  slotHalf: number;         // half width of horn slot
  bankAngle: number;        // fork throw limit (rad), half the lock-to-lock throw
  balanceHz: number;        // 3 Hz -> 21,600 vph
  balanceJ: number;
  balanceDamp: number;
  forkJ: number;
  escapeJ: number;          // includes reflected train inertia
  driveTorque: number;      // escape-wheel torque at full wind
  torqueFloor: number;      // fraction of torque at zero wind
  friction: number;         // Coulomb cap on tangential contact impulse
  eImpLen?: number;         // drop tuning: entry impulse face length
  xImpLen?: number;         // drop tuning: exit impulse face length
  reserveSeconds: number;   // accelerated power reserve (documented)
  windPerTurn: number;
  fixedDt: number;          // escapement substep
  seedKick: number;         // restart-from-stop seed (documented)
};

export const WATCH_DEFAULTS: WatchPhysics = {
  escapeTeeth: 15,
  escapeR: 10,
  forkPivot: 13.4,   // ~1.4 x tip radius: pallet ARBOR (zero-motion point of the reference fork), not the slot neck
  balancePivot: 12,
  rollerR: 2.5,
  hornR: 9.5,
  slotHalf: 0.5,
  bankAngle: 0.06,   // total throw 6.9 deg; engaged lock depth ~0.45, disengaged clearance ~0.4
  balanceHz: 3,
  balanceJ: 1,
  balanceDamp: 0.35,
  forkJ: 0.02,   // heavy enough that the flip DRAGS the balance (impulse delivery); 0.0045 outran the jewel, 0.03 stalled
  escapeJ: 0.5,
  driveTorque: 3000,
  torqueFloor: 0.28,
  friction: 0.12,
  reserveSeconds: 150,
  windPerTurn: 0.22,
  fixedDt: 1 / 960,
  seedKick: 0.6,
};

/* Exact train: tooth counts. Angles derive from the escape wheel angle. */
export const TRAIN = {
  barrelTeeth: 72, centerPinion: 12,   // barrel -> center 6:1
  centerTeeth: 80, thirdPinion: 10,    // center -> third 8:1
  thirdTeeth: 75, fourthPinion: 10,    // third -> fourth 7.5:1
  fourthTeeth: 72, escapePinion: 6,    // fourth -> escape 12:1 (2 beats per tooth: 30 beats/rev, 5 s/rev at 6 beats/s)
  motionWorks: 12,                     // hour hand = minute / 12
};
const R_E4 = TRAIN.fourthTeeth / TRAIN.escapePinion;   // 10
const R_43 = TRAIN.thirdTeeth / TRAIN.fourthPinion;    // 7.5
const R_3C = TRAIN.centerTeeth / TRAIN.thirdPinion;    // 8
const R_CB = TRAIN.barrelTeeth / TRAIN.centerPinion;   // 6

export type WatchState = {
  e: number; we: number;       // escape wheel angle, angular velocity
  p: number; wp: number;       // pallet fork
  b: number; wb: number;       // balance
  wind: number;                // mainspring wind 0..1
  crown: number;               // crown rotation (renderer + ratchet)
  beats: number;               // beat counter: lock-ARREST events (haptics/tests)
  lockHeld: boolean;           // a tooth currently rests on a lock face
  amp: number;                 // recent amplitude estimate (rad)
  t: number;
  acc: number;                 // substep accumulator
  seeded: boolean;             // restart seed consumed
  stopped: boolean;
};

export function createWatch(p: WatchPhysics): WatchState {
  const w0 = 2 * Math.PI * p.balanceHz;
  return {
    // tooth 3 rests on the engaged exit shelf; gentle balance start (the
    // escapement itself must pump the amplitude up - that is the validation)
    e: -0.2796, we: 0, p: -p.bankAngle, wp: 0,   // tooth 3 on the exit lock face at -bank
    b: 0, wb: w0 * 4.4,   // running amplitude; unlock needs b ~ 1.5+ against full-wind draw
    wind: 1, crown: 0, beats: 0, lockHeld: true,
    amp: 4.4, t: 0, acc: 0, seeded: true, stopped: false,
  };
}

/* ------- gear train: exact derived angles (meshing phase offsets are
   visual alignment constants, they do not affect ratios) ------- */
export function trainAngles(e: number) {
  const fourth = -e / R_E4;
  const third = -fourth / R_43;
  const center = -third / R_3C;
  const barrel = -center / R_CB;
  return {
    escape: e, fourth, third, center, barrel,
    minute: center, second: fourth, hour: center / TRAIN.motionWorks,
  };
}

export function windCrown(s: WatchState, p: WatchPhysics, turns: number) {
  s.crown += turns * 2 * Math.PI;
  if (turns > 0) s.wind = Math.min(1, s.wind + turns * p.windPerTurn);
  if (s.stopped && s.wind > 0.04 && !s.seeded) {
    /* documented seed: the handling jolt that starts a real movement */
    s.wb = (s.b >= 0 ? 1 : -1) * p.seedKick * 2 * Math.PI * p.balanceHz;
    s.seeded = true; s.stopped = false;
  }
}

/* ------- escapement geometry -------
   World frame: y-up math coords. Escape wheel center at origin, tip circle
   escapeR. THE WHEEL TURNS CLOCKWISE (e decreases under mainspring torque).
   Pallet pivot ABOVE the wheel at (0, forkPivot) - the long anchor arms are
   load-bearing: a short straight fork makes correct draw physically
   impossible (probe2 cone search, see STATUS.md). Geometry measured from the
   Wikimedia anchor-escapement reference and verified against the three
   contact constraints (resists tooth, tooth outside, draw toward the engaged
   banking) in probe3.mjs:
   - entry stone at polar 120 deg: a vertical slab; its LEFT face is the
     locking face (normal (-1,0)), its BOTTOM face is the impulse face
     (normal (0,-1)); engaged at the +banking.
   - exit stone at polar 60 deg: its locking face is a shallow shelf tilted
     12 deg from the tooth travel direction (the draw angle: the locked
     tooth wedges the fork onto its banking), its impulse face rises at
     30 deg with normal (-0.5, 0.866); engaged at the -banking.
   Corner separation 60 deg = 2.5 tooth pitches: the half-pitch stagger that
   gives exactly 2 beats per tooth is structural, not scheduled. */

type Face = { ax: number; ay: number; nx: number; ny: number; tx: number; ty: number; len: number };

/* fork-local face definitions at fork angle 0 (pivot at local origin);
   world = rotate(p) + (0, forkPivot). Positions from the measurements
   above, scaled to escapeR = 10. */
/* verified by probe4.mjs (resist / draw sign / creep / corner-cone margin):
   entry corner (-4.82,-4.72) polar 119 deg, exit corner (5.72,-5.23) polar
   55 deg; engaged depth 0.4 at the banking, clearance ~0.34 at the other. */
/* corners at world polars 118.5 / 55.5 deg: separation 63 deg = 10.5
   half-pitches, so alternating arrests each advance the wheel exactly one
   half-pitch (2 beats per tooth is structural) */
const ENTRY_LOCK = { ax: -4.738, ay: -4.674, tx: -0.292, ty: 0.957, nx: -0.957, ny: -0.292, len: 1.1 };
const ENTRY_IMP  = { ax: -4.738, ay: -4.674, tx: 1, ty: 0, nx: 0, ny: -1, len: 0.9 };   // extends INWARD from the corner (inside the tooth circle when engaged)
const EXIT_LOCK  = { ax: 5.514, ay: -5.316, tx: 0.743, ty: 0.669, nx: -0.669, ny: 0.743, len: 1.4 };
const EXIT_IMP   = { ax: 5.625, ay: -5.216, tx: 0.342, ty: -0.940, nx: -0.940, ny: -0.342, len: 1.2 };   // extends INWARD from the corner

function rotFace(local: Face, c: number, s: number, F: number, out: Face) {
  out.ax = local.ax * c - local.ay * s;
  out.ay = local.ax * s + local.ay * c + F;
  out.tx = local.tx * c - local.ty * s;
  out.ty = local.tx * s + local.ty * c;
  out.nx = local.nx * c - local.ny * s;
  out.ny = local.nx * s + local.ny * c;
  out.len = local.len;
}

/* Point-vs-face contact: returns penetration depth (>=0 means touching). */
function contactFace(tx: number, ty: number, f: Face): number {
  const rx = tx - f.ax, ry = ty - f.ay;
  const u = rx * f.tx + ry * f.ty;
  if (u < -0.08 || u > f.len + 0.08) return -1;
  const d = rx * f.nx + ry * f.ny;
  // skin 0.06; deeper than 0.35 the point has tunneled through the thin
  // stone model - release it (a dropped lock recoils and the next tooth locks)
  return d <= 0.06 && d >= -0.5 ? -d : -1;
}

/* One escapement substep: semi-implicit Euler + sequential impulses. */
function substep(s: WatchState, p: WatchPhysics, dt: number, geo: Face[]) {
  const k = (2 * Math.PI * p.balanceHz) ** 2 * p.balanceJ;
  const torque = p.driveTorque * (p.torqueFloor + (1 - p.torqueFloor) * s.wind);
  const F = p.forkPivot;

  // free dynamics; CLOCKWISE wheel: drive torque is negative
  s.we += (-torque / p.escapeJ) * dt;
  s.we *= 1 - 0.04 * dt * 60 * 0.001;  // tiny train drag
  s.wb += ((-k * s.b - p.balanceDamp * s.wb) / p.balanceJ) * dt;
  s.wp *= 1 - 2.2 * dt; // pivot friction (fork is contact-driven)

  // banking pins as hard one-sided constraints (before contacts, so the
  // draw presses the fork onto the pin instead of rattling)
  if (s.p >= p.bankAngle && s.wp > 0) s.wp = 0;
  if (s.p <= -p.bankAngle && s.wp < 0) s.wp = 0;

  const c = Math.cos(s.p), sn = Math.sin(s.p);
  rotFace(ENTRY_LOCK, c, sn, F, geo[0]);
  rotFace(p.eImpLen ? { ...ENTRY_IMP, len: p.eImpLen } : ENTRY_IMP, c, sn, F, geo[1]);
  rotFace(EXIT_LOCK, c, sn, F, geo[2]);
  rotFace(p.xImpLen ? { ...EXIT_IMP, len: p.xImpLen } : EXIT_IMP, c, sn, F, geo[3]);

  const pitch = (2 * Math.PI) / p.escapeTeeth;
  let lockNow = false;
  for (let kTooth = 0; kTooth < p.escapeTeeth; kTooth++) {
    const a = s.e + kTooth * pitch;
    const tx = p.escapeR * Math.cos(a), ty = p.escapeR * Math.sin(a);
    const vtx = -s.we * ty, vty = s.we * tx; // point velocity = w x r
    for (let i = 0; i < 4; i++) {
      const face = geo[i];
      const pen = contactFace(tx, ty, face);
      if (pen < 0) continue;
      if (i === 0 || i === 2) lockNow = true;
      const cpx = face.ax, cpy = face.ay - F;   // lever from fork pivot
      const fvx = -s.wp * cpy, fvy = s.wp * cpx;
      const rvx = vtx - fvx, rvy = vty - fvy;
      const vn = rvx * face.nx + rvy * face.ny;
      if (vn >= 0 && pen < 0.02) continue; // separating and not sunk
      const reX = tx, reY = ty;
      const ce = (reX * face.ny - reY * face.nx) ** 2 / p.escapeJ;
      let cf = (cpx * face.ny - cpy * face.nx) ** 2 / p.forkJ;
      // banking pin is a bilateral constraint at its limit: if this contact
      // presses the fork INTO the pin it already rests on, the pin (not the
      // fork inertia) absorbs it - treat the fork as grounded for this contact
      const cn = cpx * face.ny - cpy * face.nx;
      const dwpSign = -cn; // sign of fork velocity change per unit j (j >= 0)
      const onPin =
        (s.p >= p.bankAngle - 1e-6 && dwpSign > 0) ||
        (s.p <= -p.bankAngle + 1e-6 && dwpSign < 0);
      if (onPin) cf = 0;
      const meff = ce + cf;
      if (meff <= 0) continue;
      let j = -vn / meff;  // restitution 0; positional correction is separate below
      if (j < 0) j = 0;
      const tnx = -face.ny, tny = face.nx;
      const vt = rvx * tnx + rvy * tny;
      const ceT = (reX * tny - reY * tnx) ** 2 / p.escapeJ;
      let cfT = (cpx * tny - cpy * tnx) ** 2 / p.forkJ;
      if (onPin) cfT = 0;
      let jt = -vt / (ceT + cfT + 1e-9);
      const cap = p.friction * j;
      if (jt > cap) jt = cap; else if (jt < -cap) jt = -cap;
      const ix = face.nx * j + tnx * jt, iy = face.ny * j + tny * jt;
      s.we += (reX * iy - reY * ix) / p.escapeJ;
      s.wp -= (cpx * iy - cpy * ix) / p.forkJ;
    }
  }

  // positional depenetration (pseudo-impulse, no kinetic energy injection):
  // split between wheel and fork by inverse effective mass
  for (let kTooth = 0; kTooth < p.escapeTeeth; kTooth++) {
    const a = s.e + kTooth * pitch;
    const tx = p.escapeR * Math.cos(a), ty = p.escapeR * Math.sin(a);
    for (let i = 0; i < 4; i++) {
      const face = geo[i];
      const pen = contactFace(tx, ty, face);
      if (pen <= 0.005) continue;
      const cpx = face.ax, cpy = face.ay - F;
      const reX = tx, reY = ty;
      const ce = (reX * face.ny - reY * face.nx) ** 2 / p.escapeJ;
      const cf = (cpx * face.ny - cpy * face.nx) ** 2 / p.forkJ;
      const meff = ce + cf;
      if (meff <= 0) continue;
      const rn = reX * face.ny - reY * face.nx;
      const cn = cpx * face.ny - cpy * face.nx;
      const dP = -((cn / p.forkJ) * 0.4 * Math.min(pen - 0.004, 0.3)) / meff;
      const pinned =
        (s.p >= p.bankAngle - 1e-6 && dP > 0) || (s.p <= -p.bankAngle + 1e-6 && dP < 0);
      if (pinned) {
        // fork is on its banking: the whole correction goes to the wheel
        if (Math.abs(rn) > 1e-6) s.e += (0.8 * Math.min(pen - 0.004, 0.3)) / rn;
      } else {
        const lambda = 0.4 * Math.min(pen - 0.004, 0.3) / meff;
        s.e += (rn / p.escapeJ) * lambda;
        s.p += dP;
      }
    }
  }

  // roller jewel vs fork slot walls: unlock + impulse transfer to balance
  {
    const Bx = 0, By = F + p.balancePivot;
    const ja = s.b;
    const jx = Bx + p.rollerR * Math.sin(ja), jy = By - p.rollerR * Math.cos(ja);
    const hx0 = 0, hy0 = p.hornR;         // fork-local: slot toward balance
    const hx = hx0 * c - hy0 * sn, hy = hx0 * sn + hy0 * c + F;
    const ax = -sn, ay = c;               // fork axis (toward balance)
    const dx = jx - hx, dy = jy - hy;
    const along = dx * ax + dy * ay;
    const side = dx * ay - dy * ax;
    const wxn = ay, wyn = -ax;
    if (Math.abs(along) < 1.6 && Math.abs(side) < p.slotHalf + 0.9) {
      const penS = Math.abs(side) - p.slotHalf;
      if (penS > 0) {
        const sgn = side > 0 ? 1 : -1;
        const nx = wxn * sgn, ny = wyn * sgn;
        const vjx = s.wb * p.rollerR * Math.cos(ja), vjy = s.wb * p.rollerR * Math.sin(ja);
        const cpx = hx, cpy = hy - F;
        const fvx = -s.wp * cpy, fvy = s.wp * cpx;
        const vn = (vjx - fvx) * nx + (vjy - fvy) * ny;
        const rjX = jx - Bx, rjY = jy - By;
        const cb = (rjX * ny - rjY * nx) ** 2 / p.balanceJ;
        const cf = (cpx * ny - cpy * nx) ** 2 / p.forkJ;
        const meff = cb + cf;
        if (meff > 0 && (vn < 0 || penS > 0.02)) {
          let j = -vn / meff;
          if (j < 0) j = 0;
          s.wb += (rjX * (ny * j) - rjY * (nx * j)) / p.balanceJ;
          s.wp -= (cpx * (ny * j) - cpy * (nx * j)) / p.forkJ;
        }
      }
    }
  }

  // banking pins: position projection, no bounce
  if (s.p > p.bankAngle) { s.p = p.bankAngle; if (s.wp > 0) s.wp = 0; }
  if (s.p < -p.bankAngle) { s.p = -p.bankAngle; if (s.wp < 0) s.wp = 0; }

  // banking pin hard stop at integration (contacts may set wp after the
  // pre-clamp; never let one substep jump past the pin)
  if ((s.p >= p.bankAngle && s.wp > 0) || (s.p <= -p.bankAngle && s.wp < 0)) s.wp = 0;
  if (s.p + s.wp * dt > p.bankAngle) { s.p = p.bankAngle; s.wp = 0; }
  else if (s.p + s.wp * dt < -p.bankAngle) { s.p = -p.bankAngle; s.wp = 0; }
  // integrate (clamps keep a missed contact from running away)
  if (s.we > 40) s.we = 40; else if (s.we < -40) s.we = -40;
  if (s.wp > 120) s.wp = 120; else if (s.wp < -120) s.wp = -120;
  s.e += s.we * dt;
  s.p += s.wp * dt;
  s.b += s.wb * dt;

  // beat counting: a beat is a lock ARREST (a tooth lands on a lock face),
  // not a fork sign flip - the fork can flap in the slot clearance without
  // the escapement beating
  if (lockNow && !s.lockHeld) s.beats++;
  s.lockHeld = lockNow;

  // amplitude estimate (slow tracker)
  const ab = Math.abs(s.b);
  if (ab > s.amp) s.amp = ab; else s.amp += (ab - s.amp) * dt * 0.5;

  // power reserve
  s.wind = Math.max(0, s.wind - dt / p.reserveSeconds);
  if (s.amp < 0.25 && Math.abs(s.wb) < 0.8 && s.wind <= 0.04) {
    s.stopped = true; s.seeded = false;
  }
}

export function stepWatch(s: WatchState, p: WatchPhysics, dtFrame: number) {
  const geo: Face[] = [newFace(), newFace(), newFace(), newFace()];
  s.acc = Math.min(s.acc + dtFrame, 0.12);
  const n = Math.floor(s.acc / p.fixedDt);
  for (let i = 0; i < n; i++) { substep(s, p, p.fixedDt, geo); s.t += p.fixedDt; }
  s.acc -= n * p.fixedDt;
}

function newFace(): Face {
  return { ax: 0, ay: 0, nx: 0, ny: 0, tx: 0, ty: 0, len: 0 };
}

/* watch3d.ts - true 3D mesh engine for the mechanical watch, shared TS.
   No GL: builds real 3D meshes (lathes, extruded gears, boxes), projects
   through a perspective camera, flat-shades with a two-light rig + Blinn
   specular, painter-sorts, and emits a flat triangle list that BOTH the
   native Skia renderer (createPicture) and the web Canvas2D renderer draw.
   Sim units: escape wheel tip radius = 10, dial radius ~46. +Z faces the
   viewer (out of the dial). */

export type Tri = {
  x0: number; y0: number; x1: number; y1: number; x2: number; y2: number;
  r: number; g: number; b: number;
};

type V3 = [number, number, number];

export type Mesh = {
  pos: Float32Array;      // xyz per vertex
  idx: Uint32Array;       // 3 per triangle
  col: V3;                // base color 0..1
  metal: number;          // 0 dielectric .. 1 metal (specular strength/tint)
  spin?: { axis: V3; center: V3; angle: number };  // rigid transform per frame
};

/* ---------- mesh builders ---------- */

function pushTri(p: number[], i: number[], a: V3, b: V3, c: V3) {
  const base = p.length / 3;
  p.push(...a, ...b, ...c);
  i.push(base, base + 1, base + 2);
}

/** Surface of revolution around the Y... around the Z axis. profile = [r, z][]. */
export function lathe(profile: [number, number][], seg: number, col: V3, metal: number): Mesh {
  const p: number[] = [], idx: number[] = [];
  const n = profile.length;
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * 2 * Math.PI, a1 = ((s + 1) / seg) * 2 * Math.PI;
    const c0 = Math.cos(a0), s0 = Math.sin(a0), c1 = Math.cos(a1), s1 = Math.sin(a1);
    for (let k = 0; k < n - 1; k++) {
      const [r0, z0] = profile[k], [r1, z1] = profile[k + 1];
      const A: V3 = [r0 * c0, r0 * s0, z0], B: V3 = [r1 * c0, r1 * s0, z1];
      const C: V3 = [r1 * c1, r1 * s1, z1], D: V3 = [r0 * c1, r0 * s0, z0];
      if (r0 > 1e-6 && r1 > 1e-6) { pushTri(p, idx, A, B, C); pushTri(p, idx, A, C, D); }
      else if (r1 > 1e-6) pushTri(p, idx, A, B, C);       // r0 = 0: A == D on the axis
      else if (r0 > 1e-6) pushTri(p, idx, A, D, B);       // r1 = 0: B == C on the axis
    }
  }
  return { pos: new Float32Array(p), idx: new Uint32Array(idx), col, metal };
}

/** Extrude a 2D polygon (CCW) to z0..z1 with caps. Polygon must be convex-ish
   or fan-triangulable from vertex 0; gear/star profiles qualify if ordered. */
export function extrude(pts: [number, number][], z0: number, z1: number, col: V3, metal: number): Mesh {
  const p: number[] = [], idx: number[] = [];
  const n = pts.length;
  for (let i = 0; i < n; i++) {
    const [x0, y0] = pts[i], [x1, y1] = pts[(i + 1) % n];
    pushTri(p, idx, [x0, y0, z0], [x1, y1, z0], [x1, y1, z1]);
    pushTri(p, idx, [x0, y0, z0], [x1, y1, z1], [x0, y0, z1]);
  }
  for (let i = 1; i < n - 1; i++) {   // top cap (CCW from above)
    pushTri(p, idx, [pts[0][0], pts[0][1], z1], [pts[i][0], pts[i][1], z1], [pts[i + 1][0], pts[i + 1][1], z1]);
  }
  for (let i = 1; i < n - 1; i++) {   // bottom cap
    pushTri(p, idx, [pts[0][0], pts[0][1], z0], [pts[i + 1][0], pts[i + 1][1], z0], [pts[i][0], pts[i][1], z0]);
  }
  return { pos: new Float32Array(p), idx: new Uint32Array(idx), col, metal };
}

/** Annulus (ring) extruded: outer + inner walls + two ring caps. */
export function ring(rOut: number, rIn: number, z0: number, z1: number, seg: number, col: V3, metal: number): Mesh {
  const p: number[] = [], idx: number[] = [];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * 2 * Math.PI, a1 = ((s + 1) / seg) * 2 * Math.PI;
    const c0 = Math.cos(a0), s0 = Math.sin(a0), c1 = Math.cos(a1), s1 = Math.sin(a1);
    const O0: V3 = [rOut * c0, rOut * s0, z0], O1: V3 = [rOut * c1, rOut * s1, z0];
    const o0: V3 = [rOut * c0, rOut * s0, z1], o1: V3 = [rOut * c1, rOut * s1, z1];
    const I0: V3 = [rIn * c0, rIn * s0, z0], I1: V3 = [rIn * c1, rIn * s1, z0];
    const i0: V3 = [rIn * c0, rIn * s0, z1], i1: V3 = [rIn * c1, rIn * s1, z1];
    pushTri(p, idx, O0, O1, o1); pushTri(p, idx, O0, o1, o0);       // outer wall
    pushTri(p, idx, I0, i1, I1); pushTri(p, idx, I0, i0, i1);       // inner wall
    pushTri(p, idx, o0, o1, i1); pushTri(p, idx, o0, i1, i0);       // top ring
    pushTri(p, idx, O0, I1, O1); pushTri(p, idx, O0, I0, I1);       // bottom ring
  }
  return { pos: new Float32Array(p), idx: new Uint32Array(idx), col, metal };
}

/** Spoked wheel: rim ring + hub + `spokes` tapered arms, all in one mesh. */
export function spokedWheel(rOut: number, rIn: number, hubR: number, z0: number, z1: number, spokes: number, col: V3, metal: number): Mesh {
  const parts: Mesh[] = [ring(rOut, rIn, z0, z1, 40, col, metal)];
  const armW = (rIn - hubR) * 0.42;
  for (let s = 0; s < spokes; s++) {
    const a = (s / spokes) * 2 * Math.PI;
    const ca = Math.cos(a), sa = Math.sin(a);
    const px = -sa, py = ca;  // tangent
    const w0 = armW * 0.55, w1 = armW;
    const quad: [number, number][] = [
      [hubR * ca + px * w0, hubR * sa + py * w0],
      [rIn * ca + px * w1, rIn * sa + py * w1],
      [rIn * ca - px * w1, rIn * sa - py * w1],
      [hubR * ca - px * w0, hubR * sa - py * w0],
    ];
    parts.push(extrude(quad, z0, z1, col, metal));
  }
  parts.push(lathe([[hubR, z0], [hubR, z1], [0, z1], [0, z0]], 20, col, metal));
  return merge(parts);
}

/** Toothed gear: alternating root/tip radius star profile, extruded. */
export function gear(teeth: number, rootR: number, tipR: number, z0: number, z1: number, col: V3, metal: number): Mesh {
  const pts: [number, number][] = [];
  const step = (2 * Math.PI) / teeth;
  for (let i = 0; i < teeth; i++) {
    const a = i * step;
    // trapezoid tooth: root 30%, rise 20%, tip 10%, fall 40% (club-ish lean)
    const prof: [number, number][] = [
      [a, rootR], [a + 0.30 * step, rootR], [a + 0.42 * step, tipR],
      [a + 0.52 * step, tipR], [a + 0.60 * step, rootR],
    ];
    for (const [aa, rr] of prof) pts.push([rr * Math.cos(aa), rr * Math.sin(aa)]);
  }
  return extrude(pts, z0, z1, col, metal);
}

export function merge(meshes: Mesh[]): Mesh {
  let np = 0, ni = 0;
  for (const m of meshes) { np += m.pos.length; ni += m.idx.length; }
  const pos = new Float32Array(np), idx = new Uint32Array(ni);
  let op = 0, oi = 0;
  for (const m of meshes) {
    pos.set(m.pos, op);
    const vb = op / 3;
    for (let k = 0; k < m.idx.length; k++) idx[oi + k] = m.idx[k] + vb;
    op += m.pos.length; oi += m.idx.length;
  }
  return { pos, idx, col: meshes[0].col, metal: meshes[0].metal };
}

export function box(cx: number, cy: number, cz: number, sx: number, sy: number, sz: number, col: V3, metal: number): Mesh {
  const x0 = cx - sx / 2, x1 = cx + sx / 2, y0 = cy - sy / 2, y1 = cy + sy / 2, z0 = cz - sz / 2, z1 = cz + sz / 2;
  return extrude([[x0, y0], [x1, y0], [x1, y1], [x0, y1]], z0, z1, col, metal);
}

/* ---------- transforms ---------- */

function rotZ(v: V3, a: number): V3 {
  const c = Math.cos(a), s = Math.sin(a);
  return [v[0] * c - v[1] * s, v[0] * s + v[1] * c, v[2]];
}

/** translate + rotate a mesh's positions in place (bake). */
export function bake(m: Mesh, dx: number, dy: number, dz: number, rz = 0): Mesh {
  for (let i = 0; i < m.pos.length; i += 3) {
    const v = rotZ([m.pos[i], m.pos[i + 1], m.pos[i + 2]], rz);
    m.pos[i] = v[0] + dx; m.pos[i + 1] = v[1] + dy; m.pos[i + 2] = v[2] + dz;
  }
  return m;
}

/* ---------- camera + shading ---------- */

export type Camera = { yaw: number; pitch: number; dist: number; fov: number; cx: number; cy: number };

const KEY: V3 = norm([-0.62, -0.28, 0.55]);   // grazing key from upper left (speculars reach the camera)
const FILL: V3 = norm([0.8, 0.35, 0.4]);

function norm(v: V3): V3 { const l = Math.hypot(v[0], v[1], v[2]); return [v[0] / l, v[1] / l, v[2] / l]; }

/** Render the scene to a painter-sorted (far-first) flat triangle list in
   a size x size square. Allocation-free inner loop (UI-thread frame budget);
   lights ride with the camera so the rig is stable. Meshes with
   convex=true skip the per-triangle sort (drawn in index order). */
const ZKEY = new Float64Array(65536);
const ZIDX = new Uint32Array(65536);

export function renderFrame(meshes: Mesh[], cam: Camera, size: number, out: Tri[]): void {
  out.length = 0;
  let zCount = 0;
  const cyw = Math.cos(cam.yaw), syw = Math.sin(cam.yaw);
  const cp = Math.cos(cam.pitch), sp = Math.sin(cam.pitch);
  const f = size / (2 * Math.tan(cam.fov / 2));
  const half = size / 2;
  const KX = KEY[0], KY = KEY[1], KZ = KEY[2];
  const FX = FILL[0], FY = FILL[1], FZ = FILL[2];
  for (let mi = 0; mi < meshes.length; mi++) {
    const m = meshes[mi];
    const spn = m.spin;
    const pos = m.pos, idx = m.idx;
    const mcr = m.col[0], mcg = m.col[1], mcb = m.col[2];
    const metal = m.metal, sm = metal > 0.5;
    const n = idx.length;
    const scx = spn ? spn.center[0] : 0, scy = spn ? spn.center[1] : 0;
    const sang = spn ? spn.angle : 0;
    const sc = Math.cos(sang), ss = Math.sin(sang);
    for (let k = 0; k < n; k += 3) {
      let vi = idx[k] * 3;
      let ax = pos[vi], ay = pos[vi + 1], az = pos[vi + 2];
      vi = idx[k + 1] * 3;
      let bx = pos[vi], by = pos[vi + 1], bz = pos[vi + 2];
      vi = idx[k + 2] * 3;
      let cx = pos[vi], cy = pos[vi + 1], cz = pos[vi + 2];
      if (spn) {
        let dx = ax - scx, dy = ay - scy;
        ax = scx + dx * sc - dy * ss; ay = scy + dx * ss + dy * sc;
        dx = bx - scx; dy = by - scy;
        bx = scx + dx * sc - dy * ss; by = scy + dx * ss + dy * sc;
        dx = cx - scx; dy = cy - scy;
        cx = scx + dx * sc - dy * ss; cy = scy + dx * ss + dy * sc;
      }
      const e1x = bx - ax, e1y = by - ay, e1z = bz - az;
      const e2x = cx - ax, e2y = cy - ay, e2z = cz - az;
      const nrx = e1y * e2z - e1z * e2y;
      const nry = e1z * e2x - e1x * e2z;
      const nrz0 = e1x * e2y - e1y * e2x;
      const nl = Math.sqrt(nrx * nrx + nry * nry + nrz0 * nrz0);
      if (nl < 1e-12) continue;
      // camera transform (+z of the scene faces the camera)
      const ax2 = ax * cyw - ay * syw, ayw = ax * syw + ay * cyw;
      const azc = ayw * sp - az * cp + cam.dist;
      const bx2 = bx * cyw - by * syw, byw = bx * syw + by * cyw;
      const bzc = byw * sp - bz * cp + cam.dist;
      const cx2 = cx * cyw - cy * syw, cyw2 = cx * syw + cy * cyw;
      const czc = cyw2 * sp - cz * cp + cam.dist;
      if (azc < 4 || bzc < 4 || czc < 4) continue;
      const ays = ayw * cp + az * sp;
      const bys = byw * cp + bz * sp;
      const cys = cyw2 * cp + cz * sp;
      // normal to camera space
      let nx = nrx * cyw - nry * syw, ny = nrx * syw + nry * cyw;
      let nyy = ny * cp + nrz0 * sp, nzz = ny * sp - nrz0 * cp;
      const flip = nzz > 0 ? -1 : 1;
      const inv = flip / nl;
      nx *= inv; nyy *= inv; nzz *= inv;
      const keyD = -(nx * KX + nyy * KY + nzz * KZ);
      const fillD = -(nx * FX + nyy * FY + nzz * FZ);
      const nd = nx * KX + nyy * KY + nzz * KZ;
      const rz = KZ - 2 * nd * nzz;
      const rx2 = KX - 2 * nd * nx;
      const ry2 = KY - 2 * nd * nyy;
      const rl = Math.sqrt(rx2 * rx2 + ry2 * ry2 + rz * rz);
      const streak = Math.abs(nx);
      let specA = Math.pow(Math.max(0, -rz / (rl > 1e-9 ? rl : 1)), 12);
      const st = streak * streak * streak * streak * streak; // |nx|^5
      const st2 = st * st * (1 - Math.abs(nzz)) * (1 - Math.abs(nzz)) * 0.9;  // |nx|^10 (1-|nz|)^2
      if (st2 > specA) specA = st2;
      const spec = specA * (0.22 + 1.0 * metal);
      const amb = 0.22;
      const dif = 0.78 * (keyD > 0 ? keyD : 0) + 0.25 * (fillD > 0 ? fillD : 0);
      let r = mcr * (amb + dif), g = mcg * (amb + dif), b = mcb * (amb + dif);
      const sa = sm ? 1.6 : 1;
      r += spec * (sm ? Math.min(1, mcr * sa) : 1);
      g += spec * (sm ? Math.min(1, mcg * sa) : 1);
      b += spec * (sm ? Math.min(1, mcb * sa) : 1);
      out.push({
        x0: half + (ax2 * f) / azc, y0: half - (ays * f) / azc,
        x1: half + (bx2 * f) / bzc, y1: half - (bys * f) / bzc,
        x2: half + (cx2 * f) / czc, y2: half - (cys * f) / czc,
        r: r > 1 ? 1 : r, g: g > 1 ? 1 : g, b: b > 1 ? 1 : b,
      });
      if (zCount < 65536) { ZKEY[zCount] = (azc + bzc + czc) / 3; ZIDX[zCount] = out.length - 1; zCount++; }
    }
  }
  // painter sort: far (large z) drawn first
  const order = ZIDX.subarray(0, zCount);
  const z = ZKEY;
  Array.prototype.sort.call(order, (a, b) => z[b] - z[a]);
  const sorted: Tri[] = new Array(zCount);
  for (let i = 0; i < zCount; i++) sorted[i] = out[ZIDX[i]];
  for (let i = 0; i < zCount; i++) out[i] = sorted[i];
  out.length = zCount;
}

/* ---------- the watch scene ----------
   Sim-consistent movement layout (escape tip R = 10):
   escape wheel at (0,-17) [sim coords offset (0,-17)], fork pivot (0,-3.6),
   balance (0,8.4). Center wheel at origin with the hands. Skeleton: no full
   dial - chapter ring + applied markers, movement visible. */

export type WatchScene = {
  statics: Mesh[];        // case, ring, plate, bridges (never spin)
  wheels: Mesh[];         // barrel, center, third, fourth, escape (spin.angle set per frame)
  fork: Mesh;             // spins about (0,-3.6)
  balance: Mesh;          // spins about (0,8.4)
  hairspring: Mesh;       // same center as balance
  hourHand: Mesh; minuteHand: Mesh; secondHand: Mesh;
};

const BRASS: V3 = [0.80, 0.62, 0.24];
const STEEL: V3 = [0.72, 0.74, 0.78];
const BLUED: V3 = [0.16, 0.28, 0.62];
const PLATE: V3 = [0.30, 0.30, 0.34];
const RUBY: V3 = [0.72, 0.10, 0.16];

function hand(len: number, w: number, tail: number, z0: number, z1: number, col: V3): Mesh {
  // tapered dauphine-ish hand pointing +Y from the center
  const pts: [number, number][] = [
    [-w * 0.5, -tail], [w * 0.5, -tail], [w * 0.42, len * 0.55], [0, len], [-w * 0.42, len * 0.55],
  ];
  return extrude(pts, z0, z1, col, 1);
}

export function buildWatchScene(): WatchScene {
  // case: clean band ring + convex bezel arc + solid back (no zigzag profiles)
  const caseBand = ring(50, 46.8, -2, 10.0, 64, STEEL, 1);   // top cap fully under the bezel bottom (10.2): no z-alternation
  const caseBack = lathe([[0, -2.8], [46.6, -2.8], [48.4, -2], [46.6, -1.7], [41.8, -1.7]], 48, STEEL, 1);   // no interior top disc: the plate covers it (fan interleave)
  const bezel = lathe([[45.8, 10.2], [50.3, 10.2], [51.2, 11.5], [49, 13.5], [45.8, 13.2], [45.8, 10.2]], 64, STEEL, 1);  // closed cross-section
  const crownX = merge([
    box(50.5, 0, 4, 3.5, 1.6, 1.6, STEEL, 1),     // stem
    box(53.5, 0, 4, 3.4, 4.6, 4.6, STEEL, 1),     // head
    box(53.5, 0, 4, 4.0, 3.4, 5.2, STEEL, 1),     // knurl cross
  ]);
  // chapter ring + applied markers
  const chapter = ring(46.55, 41.5, 6.4, 10.2, 64, [0.07, 0.07, 0.09], 0.2);   // tall rehaut, INSIDE the band inner wall (46.8) - no crossing
  const markers: Mesh[] = [];
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * 2 * Math.PI;
    const w = i % 3 === 0 ? 1.6 : 0.9;
    const m = box(0, 0, 0, w, 3.6, 0.5, STEEL, 1);
    bake(m, 43.9 * Math.sin(a), 43.9 * Math.cos(a), 10.0, -a);
    markers.push(m);
  }
  // solid mainplate disc (dark) + center medallion + balance cock
  const plate = lathe([[0, -0.8], [41.6, -0.8], [41.6, 0], [0, 0]], 56, PLATE, 0.8);
  const balCock = bake(box(0, 0, 0, 5, 14, 1.2, PLATE, 0.8), 0, 9, 6.0, 0.12);
  // gear train: z-tiered for depth separation (barrel low, rising toward escape)
  const barrel = merge([
    gear(84, 15.2, 16, 0.4, 1.6, BRASS, 1),
    spokedWheel(14.9, 14.1, 3.2, 1.6, 2.4, 6, BRASS, 1),
    lathe([[0, 0.2], [1.8, 0.2], [1.8, 3.0], [0, 3.0]], 12, STEEL, 1),
  ]);
  bake(barrel, -20, 15, 0);
  const center = merge([
    gear(80, 12.6, 13.2, 0.8, 1.6, BRASS, 1),
    spokedWheel(12.4, 11.6, 2.2, 1.6, 2.2, 5, BRASS, 1),
    lathe([[0, 0.2], [1.1, 0.2], [1.1, 8.6], [0, 8.6]], 10, STEEL, 1),
  ]);
  bake(center, 0, 2, 0);
  const third = merge([
    gear(75, 9.5, 10, 2.2, 2.9, BRASS, 1),
    spokedWheel(9.3, 8.6, 1.6, 2.9, 3.4, 5, BRASS, 1),
    lathe([[0, 1.6], [0.9, 1.6], [0.9, 3.8], [0, 3.8]], 10, STEEL, 1),
  ]);
  bake(third, 17, 11, 0);
  const fourth = merge([
    gear(72, 8.5, 9, 3.0, 3.7, BRASS, 1),
    spokedWheel(8.3, 7.6, 1.5, 3.7, 4.2, 4, BRASS, 1),
    lathe([[0, 2.4], [0.8, 2.4], [0.8, 8.8], [0, 8.8]], 10, STEEL, 1),
  ]);
  bake(fourth, 18, -7, 0);
  const escape = merge([
    gear(15, 8.5, 10, 3.4, 4.2, BRASS, 1),
    lathe([[0, 3.0], [0.8, 3.0], [0.8, 4.8], [0, 4.8]], 8, STEEL, 1),
  ]);
  bake(escape, 0, -22, 0);
  // pallet fork (sim geometry offset (0,-22): fork pivot at (0,-8.6))
  const forkOutline: [number, number][] = [
    [-3.2, 6.2], [3.2, 6.2],
    [1.1, 2.0], [6.4, -4.4], [4.4, -6.2],
    [1.6, -3.2], [-1.6, -3.2],
    [-4.4, -6.2], [-6.4, -4.4], [-1.1, 2.0],
  ];
  const forkBody = extrude(forkOutline, 4.4, 5.2, STEEL, 1);
  const entryStone = bake(box(0, 0, 0, 1.1, 2.4, 1.4, RUBY, 0.4), -4.9, -4.9, 4.8, -0.3);
  const exitStone = bake(box(0, 0, 0, 1.1, 2.4, 1.4, RUBY, 0.4), 5.2, -5.4, 4.8, 0.25);
  const fork = merge([forkBody, entryStone, exitStone]);
  bake(fork, 0, -8.6, 0);
  fork.spin = { axis: [0, 0, 1], center: [0, -8.6, 0], angle: 0 };
  // balance at (0, 3.4) above the train plane
  const balance = merge([
    ring(8.6, 7.6, 5.0, 6.0, 44, STEEL, 1),
    spokedWheel(7.6, 7.0, 1.4, 5.4, 6.0, 2, STEEL, 1),
    lathe([[0, 3.8], [0.7, 3.8], [0.7, 7.0], [0, 7.0]], 8, STEEL, 1),
  ]);
  bake(balance, 0, 3.4, 0);
  balance.spin = { axis: [0, 0, 1], center: [0, 3.4, 0], angle: 0 };
  const sp: [number, number][] = [];
  const turns = 5, steps = 140;
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * turns * 2 * Math.PI;
    const r = 1.6 + (t / (2 * Math.PI)) * 1.05;
    sp.push([r * Math.cos(t), r * Math.sin(t)]);
  }
  const hairspring = extrude(sp, 6.4, 6.7, BLUED, 0.8);
  bake(hairspring, 0, 3.4, 0);
  hairspring.spin = { axis: [0, 0, 1], center: [0, 3.4, 0], angle: 0 };
  // hands: bright steel hour/minute, red seconds
  const hourHand = hand(17, 2.8, 4, 7.6, 8.3, STEEL);
  hourHand.spin = { axis: [0, 0, 1], center: [0, 0, 0], angle: 0 };
  const minuteHand = hand(29, 2.2, 5, 8.5, 9.1, STEEL);
  minuteHand.spin = { axis: [0, 0, 1], center: [0, 0, 0], angle: 0 };
  const secondHand = merge([
    hand(36, 0.7, 7, 9.4, 9.8, RUBY),
    lathe([[0, 9.4], [1.8, 9.4], [1.8, 9.8], [0, 9.8]], 12, RUBY, 0.4),
  ]);
  secondHand.spin = { axis: [0, 0, 1], center: [0, 0, 0], angle: 0 };
  const wheelCenters: [number, number][] = [[-20, 15], [0, 2], [17, 11], [18, -7], [0, -22]];
  [barrel, center, third, fourth, escape].forEach((w, i) => {
    w.spin = { axis: [0, 0, 1], center: [wheelCenters[i][0], wheelCenters[i][1], 0], angle: 0 };
  });
  return {
    statics: [caseBand, caseBack, bezel, crownX, chapter, plate, balCock, ...markers],
    wheels: [barrel, center, third, fourth, escape],
    fork, balance, hairspring, hourHand, minuteHand, secondHand,
  };
}

/** Per-frame: set spin angles from the sim state and render everything. */
export function renderWatch(scene: WatchScene, a: {
  barrel: number; center: number; third: number; fourth: number; escape: number;
  fork: number; balance: number; hour: number; minute: number; second: number;
}, cam: Camera, size: number, out: Tri[]): void {
  scene.wheels[0].spin!.angle = a.barrel;
  scene.wheels[1].spin!.angle = a.center;
  scene.wheels[2].spin!.angle = a.third;
  scene.wheels[3].spin!.angle = a.fourth;
  scene.wheels[4].spin!.angle = a.escape;
  scene.fork.spin!.angle = a.fork;
  scene.balance.spin!.angle = a.balance;
  scene.hairspring.spin!.angle = a.balance * 0.92;   // slight lag illusion
  scene.hourHand.spin!.angle = a.hour;
  scene.minuteHand.spin!.angle = a.minute;
  scene.secondHand.spin!.angle = a.second;
  renderFrame([...scene.statics, ...scene.wheels, scene.fork, scene.balance, scene.hairspring, scene.hourHand, scene.minuteHand, scene.secondHand], cam, size, out);
}

